enum _RewardType { uang, sembako }

class _RewardCard extends StatelessWidget {
  final Map<String, dynamic> rewardData;
  final _RewardType type;
  final bool notAvailable;
  const _RewardCard({
    required this.rewardData,
    required this.type,
    this.notAvailable = false,
  });

  Color get _accent {
    switch (type) {
      case _RewardType.uang:
        return const Color(0xFF88CC0C);
      case _RewardType.sembako:
        return const Color(0xFF3A8C5C);
    }
  }


  String get _typeName {
    switch (type) {
      case _RewardType.uang:
        return 'Reward Uang';
      case _RewardType.sembako:
        return 'Reward Barang';
    }
  }

  @override
  Widget build(BuildContext context) {
    final nama = notAvailable ? _typeName : (rewardData['nama_reward'] ?? '-') as String;
    final deskripsi = notAvailable ? '' : (rewardData['deskripsi_reward'] ?? '') as String;
    final persen = notAvailable ? 0.0 : (rewardData['persentase_bagi_hasil'] as num?)?.toDouble() ?? 0;

    return GestureDetector(
      onTap: notAvailable
          ? null
          : () => Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => ListBagiHasilNasabahScreen(
                    initialTab: switch (type) {
                      _RewardType.uang => 0,
                      _RewardType.sembako => 1,
                    },
                  ),
                ),
              ),
      child: Container(
        margin: const EdgeInsets.only(bottom: 16),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color: const Color(0xFFEDEDED), width: 1.5),
        ),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(19),
          child: Stack(
            children: [
              // Satu blob halus di pojok kanan card
              Positioned(
                top: -45,
                right: -45,
                child: Container(
                  width: 130,
                  height: 120,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: (notAvailable ? const Color(0xFFCCCCCC) : _accent)
                        .withValues(alpha: 0.07),
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.all(18),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    // Tab/label berwarna di pojok kiri atas
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                      decoration: BoxDecoration(
                        color: (notAvailable ? const Color(0xFF9E9E9E) : _accent)
                            .withValues(alpha: 0.14),
                        borderRadius: BorderRadius.circular(30),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            notAvailable ? Icons.lock_outline_rounded : Icons.auto_awesome_rounded,
                            size: 13,
                            color: notAvailable ? const Color(0xFF9E9E9E) : _accent,
                          ),
                          const SizedBox(width: 6),
                          Text(
                            notAvailable
                                ? 'Belum tersedia'
                                : 'Bagi hasil ${_formatPersen(persen)}%',
                            style: TextStyle(
                              fontFamily: 'Poppins',
                              fontSize: 11,
                              fontWeight: FontWeight.w700,
                              color: notAvailable ? const Color(0xFF9E9E9E) : _accent,
                            ),
                          ),
                        ],
                      ),
                    ),

                    const SizedBox(height: 14),

                    // Judul reward
                    Text(
                      nama,
                      style: const TextStyle(
                        fontFamily: 'Poppins',
                        fontSize: 17,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFF013236),
                      ),
                    ),

                    if (deskripsi.isNotEmpty) ...[
                      const SizedBox(height: 4),
                      Text(
                        deskripsi,
                        style: const TextStyle(
                          fontFamily: 'Poppins',
                          fontSize: 11.5,
                          color: Color(0xFF888888),
                          height: 1.4,
                        ),
                      ),
                    ],

                    const SizedBox(height: 16),

                    if (notAvailable)
                      Row(
                        children: [
                          Icon(Icons.info_outline_rounded,
                              size: 14, color: Colors.grey[400]),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Text(
                              'Bank sampah kamu belum menerapkan sistem reward ini untuk nasabah',
                              style: TextStyle(
                                fontFamily: 'Poppins',
                                fontSize: 11,
                                color: Colors.grey[500],
                                height: 1.5,
                              ),
                            ),
                          ),
                        ],
                      )
                    else ...[
                      Divider(height: 1, color: Colors.grey.shade100),
                      const SizedBox(height: 12),
                      Row(
                        children: [
                          Text(
                            'Lihat riwayat bagi hasil',
                            style: TextStyle(
                              fontFamily: 'Poppins',
                              fontSize: 12,
                              fontWeight: FontWeight.w700,
                              color: _accent,
                            ),
                          ),
                          const Spacer(),
                          Container(
                            width: 26,
                            height: 26,
                            decoration: BoxDecoration(
                              color: _accent.withValues(alpha: 0.12),
                              shape: BoxShape.circle,
                            ),
                            child: Icon(Icons.arrow_forward_rounded,
                                size: 15, color: _accent),
                          ),
                        ],
                      ),
                    ],
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  String _formatPersen(double v) {
    if (v == v.truncateToDouble()) return v.toInt().toString();
    return v.toStringAsFixed(2)
        .replaceAll(RegExp(r'0+$'), '')
        .replaceAll(RegExp(r'\.$'), '');
  }
}
